orders_db = {
    101: {"owner": "alice", "total": 250},
    102: {"owner": "bob", "total": 75},
    103: {"owner": "alice", "total": 500},
}

# VULNERABLE: fetches ANY order by ID with no ownership check at all
def get_order_vulnerable(order_id, requesting_user):
    return orders_db.get(order_id)

print("alice requests order 102 (which belongs to bob):")
print(get_order_vulnerable(102, requesting_user="alice"))
print("alice can see bob's order details -- a real, classic IDOR vulnerability")

# FIX: verify the requesting user actually OWNS the resource before returning it
def get_order_secure(order_id, requesting_user):
    order = orders_db.get(order_id)
    if order is None:
        return None
    if order["owner"] != requesting_user:
        return {"error": "not authorized to view this order"}
    return order

print("secure: alice requests order 102 (bob's order):", get_order_secure(102, "alice"))
print("secure: alice requests order 101 (her own order):", get_order_secure(101, "alice"))

