# Simulating the CONCEPT of worm self-propagation -- a pure logic simulation,
# no real network activity or actual code execution
class SimulatedNetwork:
    def __init__(self, hosts):
        self.hosts = {h: {"infected": False} for h in hosts}
        self.connections = {
            "host_a": ["host_b", "host_c"], "host_b": ["host_a", "host_d"],
            "host_c": ["host_a"], "host_d": ["host_b", "host_e"], "host_e": ["host_d"],
        }

    def infect(self, host):
        if self.hosts[host]["infected"]:
            return
        self.hosts[host]["infected"] = True
        print(f"  {host} infected")
        for neighbor in self.connections.get(host, []):   # WORM: auto-spreads, no user action
            self.infect(neighbor)

net = SimulatedNetwork(["host_a", "host_b", "host_c", "host_d", "host_e"])
net.infect("host_a")
print("final state:", {h: v["infected"] for h, v in net.hosts.items()})

