import json

# OVERLY PERMISSIVE: grants EVERY action on EVERY resource -- a real, common misconfiguration
overly_permissive = {
    "Version": "2012-10-17",
    "Statement": [
        {"Effect": "Allow", "Action": "*", "Resource": "*"}
    ]
}

# LEAST PRIVILEGE: grants only the specific actions needed, on only the specific resource
least_privilege = {
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Action": ["s3:GetObject", "s3:PutObject"],
            "Resource": "arn:aws:s3:::my-app-uploads/*"
        }
    ]
}
print(json.dumps(overly_permissive, indent=2))
print(json.dumps(least_privilege, indent=2))

import json

# A real, well-known misconfiguration pattern: a bucket policy making an S3 bucket
# publicly readable by ANYONE on the internet -- "Principal": "*" is the key red flag
public_bucket_policy = {
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Principal": "*",
            "Action": "s3:GetObject",
            "Resource": "arn:aws:s3:::my-company-backups/*"
        }
    ]
}
print(json.dumps(public_bucket_policy, indent=2))
print("'Principal': '*' means ANYONE on the internet, not just your own AWS account/roles")

def check_bucket_policy_risk(policy):
    risky_statements = []
    for stmt in policy.get("Statement", []):
        if stmt.get("Effect") == "Allow" and stmt.get("Principal") == "*":
            risky_statements.append(stmt)
    return risky_statements

risks = check_bucket_policy_risk(public_bucket_policy)
print(f"detected {len(risks)} publicly-accessible statement(s) -- flagged for review")
